    val obj = DataCC(42L, 3.14, true)
    var i = 0
    while (i < 1000000) {
      val _ = obj.id + obj.value + obj.flag
      i += 1
    }
  }

  @Benchmark
  def accessRegularClass(): Unit = {
    val obj = new DataClass(42L, 3.14, true)
    var i = 0
    while (i < 1000000) {
      val _ = obj.id + obj.value + obj.flag
      i += 1
    }
  }

